3|"use client";
4|
5|import { useRef, useState } from "react";
6|import { PICTURE_COPY, PictureIcon } from "./picture-copy";
7|import type { SceneCard } from "./use-pictures";
8|
9|export function ImagePane({
10|  card,
11|  onPicture,
12|  onRetry,
13|  onClear,
14|  onOpen,
15|  bare,
16|  onPictureChapter,
17|}: {
18|  card: SceneCard;
19|  onPicture: () => void;
20|  onRetry: () => void;
21|  onClear: () => void;
22|  onOpen: (src: string, caption: string, opener: HTMLElement | null) => void;
23|  // The cover shows the placeholder with no pill: nothing to picture yet.
24|  bare?: boolean;
25|  // On text pages the pill pairs the scene action with the chapter one.
26|  onPictureChapter?: ((opener: HTMLElement | null) => void) | null;
27|}) {
28|  const [expanded, setExpanded] = useState(false);
29|  const timer = useRef<number | null>(null);
30|
31|  function armExpand() {
32|    if (timer.current !== null) return;
33|    timer.current = window.setTimeout(() => {
34|      timer.current = null;
35|      setExpanded(true);
36|    }, 250);
37|  }
38|
39|  function cancelExpand() {
40|    if (timer.current !== null) {
41|      window.clearTimeout(timer.current);
42|      timer.current = null;
43|    }
44|    setExpanded(false);
45|  }
46|
47|  return (
48|    <section className="img-pane" aria-label="Illustration">
49|      <div className="frame">
50|        {card.phase === "idle" ? (
51|          <>
52|            <div className="paper-grain" aria-hidden="true">
53|              <span className="blob b1" />
54|              <span className="blob b2" />
55|              <span className="blob b3" />
56|              <span className="grain" />
57|            </div>
58|            {bare ? null : onPictureChapter ? (
59|              <span className="pic-pair" role="group" aria-label="Picture choices">
60|                <button type="button" className="pic-half" onClick={onPicture}>
61|                  <PictureIcon />
62|                  Picture this scene
63|                </button>
64|                <button type="button" className="pic-half" onClick={(e) => onPictureChapter(e.currentTarget)}>
65|                  Picture the chapter
66|                </button>
67|              </span>
68|            ) : (
69|              <button type="button" className="pic-pill" onClick={onPicture}>
70|                <PictureIcon />
71|                Picture this scene
72|              </button>
73|            )}
74|          </>
75|        ) : card.phase === "loading" ? (
76|          <div className="pane-loading" role="status">
77|            {PICTURE_COPY.loading}
78|          </div>
79|        ) : card.phase === "ready" ? (
80|          <>
81|            <img
82|              className="pane-img"
83|              src={card.url}
84|              alt={card.caption}
85|              tabIndex={0}
86|              onMouseEnter={armExpand}
87|              onMouseLeave={cancelExpand}
88|              onFocus={cancelExpand}
89|              onClick={(e) => {
90|                cancelExpand();
91|                onOpen(card.url, card.caption, e.currentTarget);
92|              }}
93|              onKeyDown={(e) => {
94|                if (e.key === "Enter") onOpen(card.url, card.caption, e.currentTarget);
95|              }}
96|            />
97|            {expanded ? (
98|              <>
99|                <div className="expand-dim" aria-hidden="true" />
100|                <img
101|                  className="expand-img"
102|                  src={card.url}
103|                  alt=""
104|                  onMouseLeave={cancelExpand}
105|                  onClick={() => {
106|                    cancelExpand();
107|                    onOpen(card.url, card.caption, null);
108|                  }}
109|                />
110|              </>
111|            ) : null}
112|          </>
113|        ) : (
114|          <div className="pane-error" role="alert">
115|            <p>{card.message}</p>
116|            <button type="button" className="retry-text" onClick={onRetry}>
117|              {PICTURE_COPY.retry}
118|            </button>
119|          </div>
120|        )}
121|      </div>
122|      {card.phase === "ready" ? (
123|        <div className="pane-cap">
124|          <span className="pane-cap-text">{card.caption}</span>
125|          <button
126|            type="button"
127|            className="pane-x"
128|            onClick={onClear}
129|            aria-label={PICTURE_COPY.remove}
130|            title={PICTURE_COPY.remove}
131|          >
132|            ×
133|          </button>
134|        </div>
135|      ) : null}
136|      {card.phase === "ready" && onPictureChapter ? (
137|        <button type="button" className="pane-chapter" onClick={(e) => onPictureChapter(e.currentTarget)}>
138|          Picture the chapter
139|        </button>
140|      ) : null}
141|    </section>
142|  );
143|}

