1|// @vitest-environment jsdom
2|// The text view mounts late on a chapter's first scene (cover first),
3|// so the mouseup listener must attach when the view appears, not on
4|// first render.
5|import { act } from "react";
6|import { createRoot } from "react-dom/client";
7|import { afterEach, expect, test, vi } from "vitest";
8|import { usePictures } from "./use-pictures";
9|
10|(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
11|
12|let lastPopover: unknown = "unset";
13|
14|function Harness({ showText }: { showText: boolean }) {
15|  const pic = usePictures({ bookId: "oz", textVersion: "v", sceneId: "c1s1", pref: { kind: "preset", id: "denslow" } });
16|  lastPopover = pic.popover;
17|  if (!showText) return <div data-testid="cover">cover</div>;
18|  return (
19|    <div ref={pic.viewRef}>
20|      <p id="c1p1" data-n="1">
21|        Dorothy lived in Kansas.
22|      </p>
23|    </div>
24|  );
25|}
26|
27|afterEach(() => {
