16|  lastPopover = pic.popover;
17|  if (!showText) return <div data-testid="cover">cover</div>;
18|  return (
19|    <div ref={pic.viewRef}>
20|      <p id="c1p1" data-n="1">
21|        Dorothy lived in Kansas.
22|      </p>
23|    </div>
24|  );
25|}
26|
27|afterEach(() => {
28|  document.body.innerHTML = "";
