59|/* "Picture this": no box. The little art is the button; label underlines on hover. */
60|.pic{appearance:none;background:none;border:0;cursor:pointer;display:inline-flex;align-items:center;gap:10px;padding:6px 4px;margin-top:14px;color:var(--accent);font-family:var(--f-btn);font-size:var(--fs-btn);line-height:1}
