12|import { useCallback, useEffect, useRef, useState } from "react";
13|import { MSG_FAILED, MSG_RETRY } from "@/core/images";
14|import { canIllustrateScene, canRetryFigure, canStart, finish, tryStart } from "./figure-placement";
15|import type { ImageResponse } from "@/core/images";
16|import { requestStyleFields, styleCredit } from "../image-style";
17|import type { ImageStylePref } from "../image-style";
18|import { pickEndN, pickStartN } from "../picture-selection";
19|import type { ParaEntry } from "../picture-selection";
