+/* Picture this button: the illustration is the button. No border,
+   no pill background. Motion only on hover and press; never idle. */
+.pic-btn {
+  position: absolute;
+  left: 50%;
+  top: 50%;
+  transform: translate(-50%, -50%);
+  appearance: none;
+  background: none;
+  border: 0;
+  padding: 6px 4px;
+  cursor: pointer;
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  white-space: nowrap;
+  font-family: var(--font-ui);
+  font-size: 13px;
+  color: var(--color-accent);
+}
+
+.pic-pair .pic-btn {
+  position: static;
+  transform: none;
+}
+
+.pic-btn-art {
+  width: 42px;
+  height: 42px;
+  flex: none;
+  display: block;
+  overflow: hidden;
+}
+
+.pic-btn-art svg {
+  width: 100%;
+  height: 100%;
+  display: block;
+  overflow: visible;
+}
+
+.pic-btn-lbl {
+  text-decoration: underline transparent 1.5px;
+  text-underline-offset: 5px;
+}
+
+.pic-btn:hover {
+  color: var(--color-accent-hover);
+}
+
+.pic-btn:hover .pic-btn-lbl,
+.pic-btn:focus-visible .pic-btn-lbl {
+  text-decoration-color: currentColor;
+}
+
+.pic-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+.pic-btn:active .pic-btn-art {
+  animation: picbtn-press 300ms ease;
+}
+
+@keyframes picbtn-press {
+  35% {
+    transform: scale(0.94);
+  }
+}
+
+.pic-btn-engraving .pic-btn-glint {
+  transform: translateX(-30px);
+}
+
+.pic-btn-engraving:hover .pic-btn-glint {
+  animation: picbtn-glint 0.7s ease 1;
+}
+
+@keyframes picbtn-glint {
+  to {
+    transform: translateX(34px);
+  }
+}
+
+.pic-btn-watercolor .pic-btn-blob {
+  transform-box: fill-box;
+  transform-origin: center;
+}
+
+.pic-btn-watercolor:hover .pic-btn-blob {
+  transform: scale(1.22);
+  opacity: 0.9;
+}
+
+.pic-btn-ink:hover .pic-btn-art svg {
+  animation: picbtn-wiggle 0.45s ease 1;
+  transform-origin: 60% 80%;
+}
+
+@keyframes picbtn-wiggle {
+  0%,
+  100% {
+    transform: rotate(0);
+  }
+
+  25% {
+    transform: rotate(-6deg);
+  }
+
+  55% {
+    transform: rotate(5deg);
+  }
+
+  80% {
+    transform: rotate(-2deg);
+  }
+}
+
+/* Drawing slot: skin paper fills the frame, status sits at the foot. */
+.pane-loading {
+  position: absolute;
+  inset: 0;
+  overflow: hidden;
+}
+
+.picdraw-art {
+  position: absolute;
+  inset: 0;
+  width: 100%;
+  height: 100%;
+}
+
+.picdraw-status {
+  position: absolute;
+  left: 0;
+  right: 0;
+  bottom: 0;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 2px;
+  padding: 10px 12px 12px;
+  font-family: var(--font-ui);
+  background: linear-gradient(transparent, rgba(255, 255, 255, 0.82));
+}
+
+html[data-theme="dark"] .picdraw-status {
+  background: linear-gradient(transparent, rgba(11, 21, 27, 0.82));
+}
+
+.picdraw-t {
+  font-size: 13px;
+  color: var(--color-text);
+}
+
+.picdraw-n {
+  font-size: 11.5px;
+  color: var(--color-text-muted);
+}
+
+/* Skin reveals: one-shot, each 900 ms or less. */
+.rv-engraving {
+  animation: rv-sepia 800ms ease;
+}
+
+@keyframes rv-sepia {
+  from {
+    opacity: 0;
+    filter: sepia(1);
+  }
+
+  to {
+    opacity: 1;
+    filter: sepia(0);
+  }
+}
+
+.rv-watercolor {
+  animation: rv-bloom 850ms ease;
+}
+
+@keyframes rv-bloom {
+  from {
+    opacity: 0;
+    filter: blur(6px) saturate(0.6);
+  }
+
+  to {
+    opacity: 1;
+    filter: blur(0) saturate(1);
+  }
+}
+
+.rv-ink {
+  animation: rv-pop 500ms cubic-bezier(0.34, 1.5, 0.64, 1);
+}
+
+@keyframes rv-pop {
+  from {
+    opacity: 0;
+    transform: scale(0.94);
+  }
+
+  to {
+    opacity: 1;
+    transform: none;
+  }
+}

